/**
 * @method
 * @name scwin.Send_form
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.Send_form = async function () {
    /* sdd-asis-lifecycle:begin Send_form — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.dataValidation()) {
        return;
    }
    const telNo = dma_hiddenStore.get("apct_tel_no1") + "-" + dma_hiddenStore.get("apct_tel_no2") + "-" + dma_hiddenStore.get("apct_tel_no3");
    const faxNo = dma_hiddenStore.get("apct_fax_no1") + "-" + dma_hiddenStore.get("apct_fax_no2") + "-" + dma_hiddenStore.get("apct_fax_no3");
    const emailNo = dma_hiddenStore.get("encryp_apct_email1") + '@' + dma_hiddenStore.get("encryp_apct_email2");
    $c.util.getComponent('ipt_encrypApctEmail').setValue(emailNo);
    $c.util.getComponent('ipt_apctTelNo').setValue(telNo);
    $c.util.getComponent('ipt_apctFaxNo').setValue(faxNo);
    if (await $c.win.confirm("신청하시겠습니까?")) {
        scwin.reg_button.setStyle("display", "none");
        const sHost = location.hostname;
        if ($c.util.getComponent('ipt_bndMktactTpCd').getValue() === "309") {
            (document.SendForm || { elements: [] }).action = "/amount/amount.do?method=frnIntBatchApplExcelUpload";
        } else {
            if ($c.util.getComponent('ipt_bndMktactTpCd').getValue() === "303" || $c.util.getComponent('ipt_bndMktactTpCd').getValue() === "304") {
                (document.SendForm || { elements: [] }).action = "/amount/amount.do?method=midRepayBatchApplExcelUpload";
            }
        }
        (document.SendForm || { elements: [] }).target = "_top";
        await scwin.tx_Send_form();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dataValidation
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dataValidation = async function () {
    /* sdd-asis-lifecycle:begin dataValidation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.str.getByteLength($c.util.getComponent('ipt_batScdaplExcelFilesNm').getValue()) == 0) {
        await $c.win.alert("일괄신청을 위한 엑셀파일을 선택해주십시오.");
        $c.util.getComponent("ipt_batScdaplExcelFilesNm").focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


