};


/**
 * @method
 * @name scwin.fileDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param mktactDiv serverDiv
 * @returns
 * @hidden N
*/
scwin.fileDown = function (mktactDiv, serverDiv) {
    /* sdd-asis-lifecycle:begin fn_file_down — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (mktactDiv === '309') {
